def parse_all(values):
    good, errors = [], []
    for v in values:
        try:
            good.append(int(v))
        except ValueError:
            errors.append(ValueError(f"bad value: {v!r}"))
    if errors:
        raise ExceptionGroup("parse failed", errors)
    return good

print(parse_all(["1", "2"]))
try:
    parse_all(["4", "x", "7", "y"])
except* ValueError as eg:
    print(len(eg.exceptions), [str(e) for e in eg.exceptions])
